BEGIN;
SELECT set_config('request.jwt.claim.sub','7058a546-747d-4b03-be5f-4fcecf901c3e',true),set_config('request.jwt.claims','{"sub":"7058a546-747d-4b03-be5f-4fcecf901c3e","role":"authenticated","is_anonymous":true}',true);
SET LOCAL ROLE authenticated;
DO $test$
DECLARE r text; response jsonb; repeated jsonb; item jsonb; total integer; j uuid;
BEGIN
 SELECT run_id INTO r FROM scored_level_runs WHERE level_id='lvl-station-1-mouth' AND status='in_progress';
 BEGIN
 PERFORM rpc_submit_activity_attempt('invented-run','content-ar-g6-digestion-v1.4.0','lvl-station-1-mouth','act-l1-1','wrong',300,'qa-invalid');
 RAISE EXCEPTION 'TEST FAILED: invented run accepted';
 EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'RUN_NOT_FOUND:%' THEN RAISE; END IF; END;
 response:=rpc_submit_activity_attempt(r,'content-ar-g6-digestion-v1.4.0','lvl-station-1-mouth','act-l1-1','wrong',300,'qa-first');
 IF response->>'revealedCorrectAnswer' IS NOT NULL OR response->>'revealedExplanationAr' IS NOT NULL OR response->>'revealedHintAr' IS NULL THEN RAISE EXCEPTION 'TEST FAILED: early disclosure'; END IF;
 repeated:=rpc_submit_activity_attempt(r,'content-ar-g6-digestion-v1.4.0','lvl-station-1-mouth','act-l1-1','wrong',300,'qa-first');
 IF NOT (repeated->>'idempotentReplay')::boolean THEN RAISE EXCEPTION 'TEST FAILED: duplicate'; END IF;
 response:=rpc_submit_activity_attempt(r,'content-ar-g6-digestion-v1.4.0','lvl-station-1-mouth','act-l1-1','opt-l1-1a',300,'qa-second');
 IF (response->>'scoreEarned')::integer<>1 OR NOT (response->>'isCorrect')::boolean THEN RAISE EXCEPTION 'TEST FAILED: second attempt score'; END IF;
 BEGIN PERFORM rpc_start_full_replay('content-ar-g6-digestion-v1.4.0',false);RAISE EXCEPTION 'TEST FAILED: unfinished replay not confirmed';EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'CONFIRMATION_REQUIRED:%' THEN RAISE; END IF;END;
 PERFORM rpc_start_full_replay('content-ar-g6-digestion-v1.4.0',true);
 FOR item IN SELECT value FROM jsonb_array_elements($answers$[{"level":"lvl-station-1-mouth","activity":"act-l1-1","answer":"opt-l1-1a","max":2},{"level":"lvl-station-1-mouth","activity":"act-l1-2","answer":"blank-l1-2-1:word-simple|blank-l1-2-2:word-energy","max":2},{"level":"lvl-station-2-esophagus","activity":"act-l2-1","answer":"zone-b","max":4},{"level":"lvl-station-2-esophagus","activity":"act-l2-2","answer":"org-mouth>org-pharynx>org-esophagus>org-stomach>org-small-intestine>org-large-intestine","max":4},{"level":"lvl-station-2-esophagus","activity":"act-l2-3","answer":"mp-epiglottis:mt-epiglottis|mp-esophagus:mt-esophagus|mp-pharynx:mt-pharynx|mp-stomach:mt-stomach","max":4},{"level":"lvl-station-2-esophagus","activity":"act-l2-4","answer":"blank-l2-4-1:word-peristalsis|blank-l2-4-2:word-accessories","max":4},{"level":"lvl-station-2-esophagus","activity":"act-l2-5","answer":"zone-a:lbl-pharynx|zone-b:lbl-epiglottis|zone-c:lbl-esophagus|zone-d:lbl-stomach","max":4},{"level":"lvl-station-3-stomach","activity":"act-l3-1","answer":"zone-c","max":6},{"level":"lvl-station-3-stomach","activity":"act-l3-2","answer":"opt-l3-2a","max":6},{"level":"lvl-station-3-stomach","activity":"act-l3-3","answer":"blank-l3-3-1:word-teeth|blank-l3-3-2:word-starch","max":6},{"level":"lvl-station-3-stomach","activity":"act-l3-4","answer":"opt-l3-4a","max":6},{"level":"lvl-station-3-stomach","activity":"act-l3-5","answer":"juice-bile:fn-bile|juice-gastric:fn-gastric|juice-pancreatic:fn-pancreatic|juice-saliva:fn-saliva","max":6},{"level":"lvl-station-3-stomach","activity":"act-l3-6","answer":"step-j1>step-j2>step-j3>step-j4","max":6},{"level":"lvl-station-3-stomach","activity":"act-l3-7","answer":"zone-a:lbl-saliva|zone-b:lbl-gastric|zone-c:lbl-bile|zone-d:lbl-pancreatic","max":6},{"level":"lvl-station-4-small-intestine","activity":"act-l4-1","answer":"opt-l4-1a","max":8},{"level":"lvl-station-4-small-intestine","activity":"act-l4-2","answer":"zone-a","max":8},{"level":"lvl-station-4-small-intestine","activity":"act-l4-3","answer":"blank-l4-3-1:word-bile|blank-l4-3-2:word-toxins","max":8},{"level":"lvl-station-4-small-intestine","activity":"act-l4-4","answer":"p-duodenum:t-duodenum|p-gallbladder:t-gallbladder|p-ileum:t-ileum|p-liver:t-liver","max":8},{"level":"lvl-station-5-absorption","activity":"act-l5-1","answer":"crit-capillary-rich:villi_surface|crit-low-absorption:smooth_surface|crit-surface-area:villi_surface||conc:conc-villi-correct","max":10},{"level":"lvl-station-5-absorption","activity":"act-l5-2","answer":"zone-a:lbl-epithelium|zone-b:lbl-capillaries|zone-c:lbl-lacteal|zone-d:lbl-base-vessels","max":10},{"level":"lvl-station-5-absorption","activity":"act-l5-3","answer":"opt-l5-3a","max":10},{"level":"lvl-station-5-absorption","activity":"act-l5-4","answer":"abs-step-1>abs-step-2>abs-step-3>abs-step-4","max":10},{"level":"lvl-station-6-large-intestine","activity":"act-l6-1","answer":"zone-c","max":12},{"level":"lvl-station-6-large-intestine","activity":"act-l6-2","answer":"blank-l6-2-1:word-water|blank-l6-2-2:word-rectum","max":12},{"level":"lvl-station-6-large-intestine","activity":"act-l6-3","answer":"ex-chew:ef-chew|ex-colon:ef-colon|ex-fiber:ef-fiber|ex-rectum:ef-rectum","max":12},{"level":"lvl-station-6-large-intestine","activity":"act-l6-4","answer":"ex-step-1>ex-step-2>ex-step-3>ex-step-4","max":12}]$answers$::jsonb) LOOP
 SELECT slr.run_id INTO r FROM scored_level_runs slr JOIN student_journeys sj USING(journey_id) WHERE sj.status='active' AND slr.level_id=item->>'level' AND slr.status='in_progress';
 response:=rpc_submit_activity_attempt(r,'content-ar-g6-digestion-v1.4.0',item->>'level',item->>'activity',item->>'answer',300,'qa-perfect-'||(item->>'activity'));
 IF NOT (response->>'isCorrect')::boolean OR (response->>'scoreEarned')::integer<>(item->>'max')::integer THEN RAISE EXCEPTION 'TEST FAILED: correct grading %',item->>'activity'; END IF;
 END LOOP;
 SELECT sum(best_completed_score) INTO total FROM student_level_best_scores WHERE content_version_id='content-ar-g6-digestion-v1.4.0';
 IF total<>186 THEN RAISE EXCEPTION 'TEST FAILED: score %',total; END IF;
 SELECT count(*) INTO total FROM student_achievements WHERE content_version_id='content-ar-g6-digestion-v1.4.0';IF total<>6 THEN RAISE EXCEPTION 'TEST FAILED: badges %',total;END IF;
 response:=rpc_get_competition_leaderboard('content-ar-g6-digestion-v1.4.0');
 IF (response->'eligibleEntries'->0->>'totalScoreEarned')::integer<>186 THEN RAISE EXCEPTION 'TEST FAILED: leaderboard';END IF;
END;$test$;
SELECT 'PASS: strict runs; hint gating; idempotency; half score; replay confirmation; all 26 answers; total 186; six badges; leaderboard eligibility' as verification;
ROLLBACK;